"""OLYMPUS map (docs/OLYMPUS_MAP.md, generated by tools/olympus_map_build.py): in step with apps.js / the Atlas districts / the tests, one row per app, 8-word descriptions, real test modules.
    python -X utf8 -m tests.test_olympus_map
"""
from __future__ import annotations

import os
import re
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RES = []


def check(name, ok, info=""):
    RES.append(bool(ok))
    print(("[PASS] " if ok else "[FAIL] ") + name + ("" if ok else f"  -> {str(info)[:500]}"), flush=True)


def main():
    tool = os.path.join(ROOT, "tools", "olympus_map_build.py")
    r = subprocess.run([sys.executable, "-I", tool, "--selftest"], capture_output=True, text=True, timeout=300)
    check("a. the builder's selftest passes", r.returncode == 0 and "ALL PASS" in r.stdout, r.stdout[-400:] + r.stderr[-200:])
    r = subprocess.run([sys.executable, "-I", tool, "--check"], capture_output=True, text=True, timeout=300)
    check("a. docs/OLYMPUS_MAP.md is exactly what `python tools/olympus_map_build.py` writes (run it after editing apps.js, the Atlas districts or a test)", r.returncode == 0, r.stdout[-300:])
    doc = open(os.path.join(ROOT, "docs", "OLYMPUS_MAP.md"), encoding="utf-8").read()
    apps = open(os.path.join(ROOT, "tools", "web_public", "jarvis", "apps.js"), encoding="utf-8").read()
    ids = re.findall(r"^\s*app\(\s*'([a-z0-9_-]+)'", apps, re.M)
    rows = [l for l in doc.split("## Every app", 1)[-1].splitlines() if re.match(r"^\| .+ \(`[a-z0-9_-]+`\)( \(retired\))? \| ", l)]
    got = [re.search(r"\(`([a-z0-9_-]+)`\)", l).group(1) for l in rows]
    check(f"b. every app in jarvis/apps.js ({len(ids)}) has exactly one row, none extra", sorted(ids) == sorted(got) and len(set(got)) == len(got), sorted(set(ids) ^ set(got)))
    cells = [[c.strip() for c in l.strip("|").split("|")] for l in rows]
    DOORS = ("NQ Bot", "Jarvis", "Websites", "Data City", "Money", "Kalshi", "Everything else")       # the 6 dashboards + Everything else (2026-11-22)
    check("b. every row has six cells, one of the arenas, a group of the 6 Home groups, a description of at most 8 words", all(len(c) == 6 and c[1] in DOORS and c[2] in ("trading", "life", "web", "data", "money", "kalshi") and 0 < len(c[3].split()) <= 8 for c in cells), [c for c in cells if not (len(c) == 6 and c[1] in DOORS)][:2])
    mods = []
    for c in cells:
        m = re.search(r"`tests\.(test_\w+)`", c[5])
        if m:
            mods.append(m.group(1))
    check("b. every test named in the map exists in tests/ (or the row says it is covered by the kit test)", all(os.path.isfile(os.path.join(ROOT, "tests", m + ".py")) for m in mods) and all(m or "olympus_kit" in c[5] for c in cells for m in [re.search(r"`tests\.(test_\w+)`", c[5])]), [m for m in mods if not os.path.isfile(os.path.join(ROOT, "tests", m + ".py"))])
    check("b. the new apps of 2026-11-10 are there with their tests: Sibyl, Kronos, Pythia, Pheme, Pnyx", all(any(f"(`{a}`)" in l and f"tests.test_{a}_page" in l for l in rows) for a in ("sibyl", "kronos", "pythia", "pheme", "pnyx")))
    check("b. the app count line matches (N apps)", re.search(rf"\n{len(ids)} apps\.", doc) is not None)
    bad = RES.count(False)
    print(f"\n{len(RES) - bad}/{len(RES)} passed")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
